568	pub const Config = struct {
569	    command: ?configpkg.Command = null,
570	
571	    /// The environment for the subprocess. init takes ownership of this
572	    /// whether or not it succeeds, so the caller must not free it after
573	    /// calling init.
574	    env: EnvMap,
