1890	        // unhinged reality.
1891	        //
1892	        // The first major issue is that on macOS, a lot of users
1893	        // put shell configurations in ~/.bash_profile instead of
1894	        // ~/.bashrc (or equivalent for another shell). This file is only
1895	        // loaded for a login shell so macOS users expect all their terminals
1896	        // to be login shells. No other platform behaves this way and its
1897	        // totally braindead but somehow the entire dev community on
1898	        // macOS has cargo culted their way to this reality so we have to
1899	        // do it...
1900	        //
1901	        // To get a login shell, you COULD just prepend argv0 with a `-`
1902	        // but that doesn't fully work because `getlogin()` C API will
1903	        // return the wrong value, SHELL won't be set, and various
1904	        // other login behaviors that macOS users expect.
1905	        //
1906	        // The proper way is to use `login(1)`. But login(1) forces
1907	        // the working directory to change to the home directory,
1908	        // which we may not want. If we specify "-l" then we can avoid
1909	        // this behavior but now the shell isn't a login shell.
1910	        //
1911	        // There is another issue: `login(1)` on macOS 14.3 and earlier
1912	        // checked for ".hushlogin" in the working directory. This means
1913	        // that if we specify "-l" then we won't get hushlogin honored
1914	        // if its in the home directory (which is standard). To get
1915	        // around this, we check for hushlogin ourselves and if present
1916	        // specify the "-q" flag to login(1).
1917	        //
1918	        // So to get all the behaviors we want, we specify "-l" but
1919	        // execute "bash" (which is built-in to macOS). We then use
1920	        // the bash builtin "exec" to replace the process with a login
1921	        // shell ("-l" on exec) with the command we really want.
1922	        //
1923	        // We use "bash" instead of other shells that ship with macOS
1924	        // because as of macOS Sonoma, we found with a microbenchmark
1925	        // that bash can `exec` into the desired command ~2x faster
1926	        // than zsh.
1927	        //
1928	        // To figure out a lot of this logic I read the login.c
1929	        // source code in the OSS distribution Apple provides for
1930	        // macOS.
1931	        //
1932	        // Awesome.
1933	        try args.append(alloc, "/usr/bin/login");
1934	        if (hush) try args.append(alloc, "-q");
1935	        try args.append(alloc, "-flp");
1936	        try args.append(alloc, username);
1937	
1938	        switch (command) {
1939	            // Direct args can be passed directly to login, since
1940	            // login uses execvp we don't need to worry about PATH
1941	            // searching.
1942	            .direct => |v| try args.appendSlice(alloc, v),
1943	
1944	            .shell => |v| {
1945	                // Use "exec" to replace the bash process with
1946	                // our intended command so we don't have a parent
1947	                // process hanging around.
1948	                const cmd = try alloc.printSentinel(
1949	                    "exec -l {s}",
1950	                    .{v},
1951	                    0,
1952	                );
1953	
1954	                // We execute bash with "--noprofile --norc" so that it doesn't
1955	                // load startup files so that (1) our shell integration doesn't
1956	                // break and (2) user configuration doesn't mess this process
1957	                // up.
1958	                try args.append(alloc, "/bin/bash");
1959	                try args.append(alloc, "--noprofile");
1960	                try args.append(alloc, "--norc");
1961	                try args.append(alloc, "-c");
1962	                try args.append(alloc, cmd);
1963	            },
1964	        }
1965	
1966	        return try args.toOwnedSlice(alloc);
1967	    }
1968	
1969	    return switch (command) {
1970	        // We need to clone the command since there's no guarantee the config remains valid.
1971	        .direct => (try command.clone(alloc)).direct,
1972	
1973	        .shell => |v| shell: {
1974	            var args: std.ArrayList([:0]const u8) = try .initCapacity(alloc, 4);
1975	            defer args.deinit(alloc);
1976	
1977	            if (comptime builtin.target.os.tag == .windows) {
1978	                // On Windows we run the shell value directly rather than
1979	                // wrapping in `cmd.exe /C <shell>`. An intermediate cmd
1980	                // process is wasteful for the common case (`wsl ~`,
1981	                // `pwsh -NoLogo`, etc.) and has visible side effects
1982	                // (extra process in the tree, per-process cmd AutoRun
1983	                // state not reaching the user's actual shell).
1984	                //
1985	                // Values with arguments are split on whitespace. This
1986	                // does not honor Windows CLI quoting rules; users who
1987	                // need quoted arguments should use the direct command
1988	                // form, which takes an argv array as-is.
1989	                //
1990	                // Note we don't free any of the memory below since it is
1991	                // allocated in the arena.
1992	                if (std.mem.indexOfAny(u8, v, " \t") == null) {
1993	                    // No arguments. If the shell is literally "cmd.exe"
1994	                    // (the default), resolve via %COMSPEC% which is the
1995	                    // documented path to the current command processor.
1996	                    // Other values are passed as-is and resolved by
1997	                    // `internal_os.path.expand` in Command.startWindows.
1998	                    const argv0 = if (std.ascii.eqlIgnoreCase(v, "cmd.exe"))
1999	                        global.environ().getAlloc(alloc, "COMSPEC") catch
2000	                            try alloc.dupe(u8, v)
2001	                    else
2002	                        try alloc.dupe(u8, v);
2003	                    try args.append(alloc, try alloc.dupeSentinel(u8, argv0), 0);
2004	                } else {
2005	                    var it = std.mem.tokenizeAny(u8, v, " \t");
2006	                    while (it.next()) |tok| {
2007	                        try args.append(alloc, try alloc.dupeSentinel(u8, tok), 0);
2008	                    }
2009	                }
2010	                break :shell try args.toOwnedSlice(alloc);
2011	            } else {
2012	                // We run our shell wrapped in `/bin/sh` so that we don't have
2013	                // to parse the command line ourselves if it has arguments.
2014	                // Additionally, some environments (NixOS, I found) use /bin/sh
2015	                // to setup some environment variables that are important to
2016	                // have set.
2017	                try args.append(alloc, "/bin/sh");
2018	                if (internal_os.isFlatpak()) try args.append(alloc, "-l");
2019	                try args.append(alloc, "-c");
2020	            }
2021	
2022	            try args.append(alloc, v);
2023	            break :shell try args.toOwnedSlice(alloc);
2024	        },
2025	    };
2026	}
