2028	/// Append a value to an environment variable such as PATH.
2029	/// The returned value is always allocated so it must be freed.
2030	fn appendEnv(
2031	    alloc: Allocator,
2032	    current: []const u8,
2033	    value: []const u8,
2034	) Allocator.Error![]u8 {
2035	    // If there is no prior value, we return it as-is
2036	    if (current.len == 0) return try alloc.dupe(u8, value);
2037	
2038	    // Otherwise we must prefix.
2039	    return try appendEnvAlways(alloc, current, value);
2040	}
2041	
2042	/// Always append value to environment, even when it is empty.
2043	/// This is useful because some env vars (like MANPATH) want there
2044	/// to be an empty prefix to preserve existing values.
2045	///
2046	/// The returned value is always allocated so it must be freed.
2047	fn appendEnvAlways(
2048	    alloc: Allocator,
2049	    current: []const u8,
2050	    value: []const u8,
2051	) Allocator.Error![]u8 {
2052	    return try alloc.print("{s}{c}{s}", .{
2053	        current,
2054	        std.fs.path.delimiter,
2055	        value,
2056	    });
2057	}
