 20	/// A struct to help execute commands on the host via the
 21	/// org.freedesktop.Flatpak.Development DBus module. This uses GIO/GLib
 22	/// under the hood.
 23	///
 24	/// This always spawns its own thread and maintains its own GLib event loop.
 25	/// This makes it easy for the command to behave synchronously similar to
 26	/// std.process.Child.
 27	///
 28	/// There are lots of chances for low-hanging improvements here (automatic
 29	/// pipes, /dev/null, etc.) but this was purpose built for my needs so
 30	/// it doesn't have all of those.
 31	///
 32	/// Requires GIO, GLib to be available and linked.
 33	pub const FlatpakHostCommand = struct {
 34	    const fd_t = posix.fd_t;
 35	    const EnvMap = std.process.Environ.Map;
 36	    const gio_c = @import("gio_c");
 37	    /// Flags for HostCommand method
 38	    ///
 39	    /// Ref: https://docs.flatpak.org/en/latest/libflatpak-api-reference.html#gdbus-method-org-freedesktop-Flatpak-Development.HostCommand
 40	    const Flags = packed struct(c_uint) {
 41	        /// Clear the environment
 42	        clear_env: bool = false,
 43	        /// Kill the sandbox when the caller disappears from the session bus
 44	        watch_bus: bool = false,
 45	        _reserved: @Int(.unsigned, @bitSizeOf(c_uint) - 2) = 0,
 46	    };
 47	
 48	    /// Argv are the arguments to call on the host with argv[0] being
 49	    /// the command to execute.
 50	    argv: []const []const u8,
 51	
 52	    /// The cwd for the new process. If this is not set then it will use
 53	    /// the current cwd of the calling process.
 54	    cwd: ?[:0]const u8 = null,
 55	
 56	    /// Environment variables for the child process. If this is null, this
 57	    /// does not send any environment variables.
 58	    env: ?*const EnvMap = null,
 59	
 60	    /// File descriptors to send to the child process. It is up to the
 61	    /// caller to create the file descriptors and set them up.
 62	    stdin: fd_t,
 63	    stdout: fd_t,
 64	    stderr: fd_t,
 65	
 66	    /// State of the process. This is updated by the dedicated thread it
 67	    /// runs in and is protected by the given lock and condition variable.
 68	    state: State = .{ .init = {} },
 69	    state_mutex: std.Io.Mutex = .init,
 70	    state_cv: std.Io.Condition = .init,
 71	
 72	    /// State the process is in. This can't be inspected directly, you
 73	    /// must use getters on the struct to get access.
 74	    const State = union(enum) {
 75	        /// Initial state
 76	        init: void,
 77	
 78	        /// Error starting. The error message is only available via logs.
 79	        /// (This isn't a fundamental limitation, just didn't need the
 80	        /// error message yet)
 81	        err: void,
 82	
 83	        /// Process started with the given pid on the host.
 84	        started: struct {
 85	            pid: u32,
 86	            loop_xev: ?*xev.Loop,
 87	            completion: ?*Completion,
 88	            subscription: gio_c.guint,
 89	            loop: *gio_c.GMainLoop,
 90	        },
 91	
 92	        /// Process exited
 93	        exited: struct {
 94	            pid: u32,
 95	            status: u8,
 96	        },
 97	    };
 98	
 99	    pub const Completion = struct {
100	        callback: *const fn (ud: ?*anyopaque, l: *xev.Loop, c: *Completion, r: WaitError!u8) void = noopCallback,
101	        c_xev: xev.Completion = .{},
102	        userdata: ?*anyopaque = null,
103	        timer: ?xev.Timer = null,
104	        result: ?WaitError!u8 = null,
105	    };
106	
107	    /// Errors that are possible from us.
108	    pub const Error = error{
109	        FlatpakMustBeStarted,
110	        FlatpakSpawnFail,
111	        FlatpakSetupFail,
112	        FlatpakRPCFail,
113	    };
114	
115	    pub const WaitError = xev.Timer.RunError || Error;
116	
117	    /// Spawn the command. This will start the host command. On return,
118	    /// the pid will be available. This must only be called with the
119	    /// state in "init".
120	    ///
121	    /// Precondition: The self pointer MUST be stable.
122	    pub fn spawn(self: *FlatpakHostCommand, alloc: Allocator) !u32 {
123	        const thread = try std.Thread.spawn(.{}, threadMain, .{ self, alloc });
124	        thread.setName(global.io(), "flatpak-host-command") catch {};
125	        // We don't track this thread, it will terminate on its own on command exit
126	        thread.detach();
127	
128	        // Wait for the process to start or error.
129	        self.state_mutex.lockUncancelable(global.io());
130	        defer self.state_mutex.unlock(global.io());
131	        while (self.state == .init) self.state_cv.waitUncancelable(global.io(), &self.state_mutex);
132	
133	        return switch (self.state) {
134	            .init => unreachable,
135	            .err => Error.FlatpakSpawnFail,
136	            .started => |v| v.pid,
137	            .exited => |v| v.pid,
138	        };
139	    }
140	
141	    /// Wait for the process to end and return the exit status. This
142	    /// can only be called ONCE. Once this returns, the state is reset.
143	    pub fn wait(self: *FlatpakHostCommand) !u8 {
144	        self.state_mutex.lockUncancelable(global.io());
145	        defer self.state_mutex.unlock(global.io());
146	
147	        while (true) {
148	            switch (self.state) {
149	                .init => return Error.FlatpakMustBeStarted,
150	                .err => return Error.FlatpakSpawnFail,
151	                .started => {},
152	                .exited => |v| {
153	                    self.state = .{ .init = {} };
154	                    self.state_cv.broadcast(global.io());
155	                    return v.status;
156	                },
157	            }
158	
159	            self.state_cv.waitUncancelable(global.io(), &self.state_mutex);
160	        }
161	    }
