347	        // Build our arguments for the file descriptors.
348	        const fd_builder = gio_c.g_variant_builder_new(gio_c.G_VARIANT_TYPE("a{uh}"));
349	        defer gio_c.g_variant_builder_unref(fd_builder);
350	        gio_c.g_variant_builder_add(fd_builder, "{uh}", @as(c_int, 0), self.stdin);
351	        gio_c.g_variant_builder_add(fd_builder, "{uh}", @as(c_int, 1), self.stdout);
352	        gio_c.g_variant_builder_add(fd_builder, "{uh}", @as(c_int, 2), self.stderr);
353	
354	        // Build our env vars
355	        const env_builder = gio_c.g_variant_builder_new(gio_c.G_VARIANT_TYPE("a{ss}"));
356	        defer gio_c.g_variant_builder_unref(env_builder);
357	        if (self.env) |env| {
358	            var it = env.iterator();
359	            while (it.next()) |pair| {
360	                const key = try arena.dupeSentinel(u8, pair.key_ptr.*, 0);
361	                const value = try arena.dupeSentinel(u8, pair.value_ptr.*, 0);
362	                gio_c.g_variant_builder_add(env_builder, "{ss}", key.ptr, value.ptr);
363	            }
364	        }
365	
366	        // Build our args
367	        const args = try arena.alloc(?[*:0]u8, self.argv.len + 1);
368	        for (0.., self.argv) |i, arg| {
369	            const argZ = try arena.dupeSentinel(u8, arg, 0);
370	            args[i] = argZ.ptr;
371	        }
