386	            @as(*const anyopaque, if (self.cwd) |*cwd| cwd.ptr else g_cwd),
387	            args.ptr,
388	            gio_c.g_variant_builder_end(fd_builder),
389	            gio_c.g_variant_builder_end(env_builder),
390	            @as(c_uint, @bitCast(flags)),
