396	        const subscription_id = gio_c.g_dbus_connection_signal_subscribe(
397	            bus,
398	            "org.freedesktop.Flatpak",
399	            "org.freedesktop.Flatpak.Development",
400	            "HostCommandExited",
401	            "/org/freedesktop/Flatpak/Development",
402	            null,
403	            0,
404	            onExit,
405	            self,
406	            null,
407	        );
408	        errdefer gio_c.g_dbus_connection_signal_unsubscribe(bus, subscription_id);
