410	        // Go!
411	        const reply = gio_c.g_dbus_connection_call_with_unix_fd_list_sync(
412	            bus,
413	            "org.freedesktop.Flatpak",
414	            "/org/freedesktop/Flatpak/Development",
415	            "org.freedesktop.Flatpak.Development",
416	            "HostCommand",
417	            params,
418	            gio_c.G_VARIANT_TYPE("(u)"),
419	            gio_c.G_DBUS_CALL_FLAGS_NONE,
420	            gio_c.G_MAXINT,
421	            fd_list,
422	            null,
423	            null,
424	            &err,
425	        ) orelse {
426	            log.warn("Flatpak.HostCommand failed: {s}", .{err.?.*.message});
427	            return Error.FlatpakRPCFail;
428	        };
429	        defer gio_c.g_variant_unref(reply);
430	
431	        var pid: u32 = 0;
432	        gio_c.g_variant_get(reply, "(u)", &pid);
433	        log.debug("HostCommand started pid={} subscription={}", .{
434	            pid,
435	            subscription_id,
436	        });
437	
438	        self.updateState(.{
439	            .started = .{
440	                .pid = pid,
441	                .subscription = subscription_id,
442	                .loop = loop,
443	                .completion = null,
444	                .loop_xev = null,
445	            },
446	        });
