   439	    const PosixCall = struct {
   440	        fn f(func: anytype, args: anytype) !usize {
   441	            while (true) {
   442	                const rc = @call(.auto, func, args);
   443	                switch (posix.errno(rc)) {
   444	                    .SUCCESS => return @intCast(rc),
   445	                    .INTR => continue,
   446	                    .AGAIN, .ACCES => return error.Locked,
   447	                    .BADF => unreachable,
   448	                    .BUSY => return error.FileBusy,
   449	                    .INVAL => unreachable, // invalid parameters
   450	                    .PERM => return error.PermissionDenied,
   451	                    .MFILE => return error.ProcessFdQuotaExceeded,
   452	                    .NOTDIR => unreachable, // invalid parameter
   453	                    .DEADLK => return error.DeadLock,
   454	                    .NOLCK => return error.LockedRegionLimitExceeded,
   455	                    else => |err| return posix.unexpectedErrno(err),
   456	                }
   457	            }
   458	        }
   459	    };
