   485	/// Wait for the command to exit and return information about how it exited.
   486	pub fn wait(self: Command, block: bool) !Exit {
   487	    if (comptime builtin.target.os.tag == .windows) {
   488	        // Block until the process exits. This returns immediately if the
   489	        // process already exited.
   490	        //
   491	        // NOTE: We can use the pid directly as posix.system.pid_t is still an
   492	        // alias for a handle under Windows. We might want to keep an eye on if
   493	        // this changes, though.
   494	        const result = windows.exp.kernel32.WaitForSingleObject(self.pid.?, windows.INFINITE);
   495	        if (result == windows.WAIT_FAILED) {
   496	            return windows.unexpectedError(windows.GetLastError());
   497	        }
   498	
   499	        var exit_code: windows.DWORD = undefined;
   500	        const has_code = windows.exp.kernel32.GetExitCodeProcess(self.pid.?, &exit_code) != windows.FALSE;
   501	        if (!has_code) {
   502	            return windows.unexpectedError(windows.GetLastError());
   503	        }
   504	
   505	        return .{ .Exited = exit_code };
   506	    }
   507	
   508	    const status: u32 = if (block) wait_block: {
   509	        var status: if (builtin.link_libc) c_int else u32 = undefined;
   510	        _ = try waitPid(self.pid.?, &status, 0);
   511	        break :wait_block @bitCast(status);
   512	    } else wait_nohang: {
   513	        // We specify NOHANG because its not our fault if the process we launch
   514	        // for the tty doesn't properly waitpid its children. We don't want
   515	        // to hang the terminal over it.
   516	        // When NOHANG is specified, waitpid will return a pid of 0 if the process
   517	        // doesn't have a status to report. When that happens, it is as though the
   518	        // wait call has not been performed, so we need to keep trying until we get
   519	        // a non-zero pid back, otherwise we end up with zombie processes.
   520	        while (true) {
   521	            var status: if (builtin.link_libc) c_int else u32 = undefined;
   522	            const pid = try waitPid(self.pid.?, &status, posix.system.W.NOHANG);
   523	            if (pid != 0) break :wait_nohang @bitCast(status);
   524	        }
   525	    };
   526	
   527	    return .init(status);
   528	}
