   530	/// Wrapper for the raw waitpid syscall. Status is only initialized on success;
   531	/// interrupted waits are retried and all other errors are propagated.
   532	fn waitPid(
   533	    pid: posix.pid_t,
   534	    status: *if (builtin.link_libc) c_int else u32,
   535	    flags: u32,
   536	) !posix.pid_t {
   537	    while (true) {
   538	        const rc = posix.system.waitpid(pid, status, @intCast(flags));
   539	        switch (posix.errno(rc)) {
   540	            .SUCCESS => return @intCast(rc),
   541	            .INTR => continue,
   542	            .CHILD => return error.NoChildProcess,
   543	            .INVAL => return error.InvalidWaitOptions,
   544	            else => |err| return posix.unexpectedErrno(err),
   545	        }
   546	    }
   547	}
